U.add('arch','echochamber',{sev:1.05,titles:['Echo','Echo echo','Ecto','E'],build:c=>{const s=c.word('X',c.r(4));return [...Array(8)].map((_,i)=>'<p style="margin:3px 0;opacity:'+(1-i*.1).toFixed(2)+'">'+s.replace(/[aeiou]/gi,(m,j)=>c.r(i*40+j)<i*.14?'':m)+'</p>').join('')}});
U.add('arch','ledger',{sev:1.3,titles:['Visitor ledger','Visits (complete)','Who was here','Ledger of one'],build:c=>{const k=c.o.k;return '<table style="width:100%;border-collapse:collapse">'+[...Array(7)].map((_,i)=>{const n=k-6+i;return '<tr><td>visit '+Math.max(0,n)+'</td><td>visitors: 1</td><td>'+(i==6?'you':c.r(20+i)<.5?'[name removed]':'[same]')+'</td></tr>'}).join('')+'</table><p>Total visitors: 1 (rounded)</p>'}});
U.add('arch','recon',{sev:1.36,ax:{n:.2,v:.2},new:'a page you already saw is rebuilt from memory, wrongly',titles:['Reconstruction','As you remember it','From memory (approx.)','Page restored'],build:c=>{const p=U.past(c),h=p.length?U.pick(p,c.r(30)):{t:'Welcome',arch:'form',k:0},L=[...Array(4)].map((_,i)=>U.wrong(c.word('L',c.r(31+i)),i=>c.r(40+i)));
 return `<p><i>This page was rebuilt from what was left of page ${h.k}, "${U.esc(h.t)}". It was a ${h.arch}. It is now this.</i></p>`+L.map((l,i)=>`<div class=row>${l}: <input value="${U.esc(i==1&&U.said.length?U.wrong(U.pick(U.said,c.r(44)),j=>c.r(50+j)):'')}" size=14></div>`).join('')}});
U.add('arch','vocab',{sev:1.45,titles:['Remaining vocabulary','Words in stock','Inventory (words)','Few'],build:c=>{const W='door room stay you light again sorry hall way exit left right blue clock chair key floor wall lamp step please hello thank nobody name stair rain coffee stop go here there where when why who not is are was the a and of to in it I'.split(' '),n=Math.max(3,Math.floor(W.length-(c.o.k-200)/6));return '<p>'+W.map((w,i)=>i<n?w:'<s style="opacity:.35">'+w+'</s>').join(' ')+'</p><p>'+Math.max(0,n)+' of '+W.length+' remain.</p>'}});
U.add('sem','postmortem',{sev:1.2,words:{B:['Acknowledge','Read the report','Continue anyway','Amend'],L:['Root cause','Impact','Timeline','Affected party (1)'],X:['Root cause: the visitor did not leave.','Impact: one hallway, indefinitely.','Timeline: 03:45. 03:45. 03:45.','Action item: nobody is assigned.','This report was written by the system it describes.'],E:['📋','🕒','❓']},titles:['Post-incident review','Root cause analysis'],mutate:(t,r)=>r<.15?t.replace(/\b(visitor|you)\b/gi,'[affected party]'):t});
