U.add('gl','langbleed',{sev:1.35,apply:c=>{const M={door:'puerta',the:'el',you:'tú',room:'Zimmer',stay:'bleib',again:'encore',light:'luz',please:'bitte',here:'aquí',sorry:'lo siento',is:'ist',and:'und',not:'nicht'},w=document.createTreeWalker(c.w,4),t=[];while(w.nextNode())if(!w.currentNode.parentNode.closest('button'))t.push(w.currentNode);t.forEach(n=>n.textContent=n.textContent.replace(/\b[A-Za-z]+\b/g,x=>M[x.toLowerCase()]&&Math.random()<.35?M[x.toLowerCase()]:x))}});
U.add('gl','wordfade',{sev:1.08,ax:{v:.1},new:'paragraphs are split into per-word spans that fade out individually over tens of seconds',apply:c=>c.w.querySelectorAll('p').forEach((p,i)=>{if(p.children.length||c.r(380+i)>.6)return;p.innerHTML=p.textContent.split(' ').map((w,j)=>`<span style="transition:opacity ${10+c.r(390+j)*40}s">${U.esc(w)}</span>`).join(' ');const S=p.querySelectorAll('span');setTimeout(()=>S.forEach((s,j)=>{if(c.r(400+j)<.5)s.style.opacity=.08}),60)})});
U.add('gl','wordrot',{sev:1.1,apply:c=>{const w=document.createTreeWalker(c.w,4),t=[];while(w.nextNode())if(!w.currentNode.parentNode.closest('button'))t.push(w.currentNode);t.forEach(n=>n.textContent=n.textContent.replace(/\b[A-Za-z]{5,}\b/g,x=>Math.random()<.12*c.o.k/200?x.slice(0,2)+'…':x))}});
U.add('snd','convroom',{sev:1.22,ax:{a:.15},new:'convolution reverb with a generated impulse response: sparse sine notes dissolve into a room that does not exist',play:(a,o,r)=>{const R=U.au.rig(a),cv=a.createConvolver(),wet=a.createGain(),b=110+r(300)*50;cv.buffer=U.au.ir(a,3.5,2);wet.gain.value=1.4;cv.connect(wet).connect(o);R.iv(()=>{const x=a.createOscillator(),e=a.createGain(),t=a.currentTime;x.frequency.value=U.au.hz(b,Math.floor(Math.random()*8));e.gain.setValueAtTime(.0001,t);e.gain.linearRampToValueAtTime(.12,t+.02);e.gain.exponentialRampToValueAtTime(.0001,t+.4);x.connect(e).connect(cv);x.start(t);x.stop(t+.5)},1800+r(301)*2500);return R.stop}});
U.add('snd','ghostchord',{sev:1.15,play:(a,o,r)=>{const b=110+r(300)*60,v=[1,1.5,2.003].map(m=>{const x=a.createOscillator(),g=a.createGain();x.type='sine';x.frequency.value=b*m;x.frequency.exponentialRampToValueAtTime(b*m*.5,a.currentTime+120);g.gain.value=.06;x.connect(g).connect(o);x.start();return x});return()=>v.forEach(x=>x.stop())}});
U.add('snd','ksdrone',{sev:1.08,ax:{a:.1},new:'Karplus-Strong plucked strings: a noise burst through a filtered feedback delay',play:(a,o,r)=>{const R=U.au.rig(a),b=82+r(300)*40,p=()=>U.au.pluck(a,o,U.au.hz(b,Math.floor(Math.random()*6)),.35);p();R.iv(()=>{if(Math.random()<.8)p()},2500+r(301)*3000);return R.stop}});